      const yawRate = clamp(-3.2 * att.yaw - 1.6 * yawInt - 0.25 * rates.yaw, -2, 2);

      lastThrust = thrust;
      lastRoll = roll;
      lastPitch = pitch;
      return { thrust, roll, pitch, yawRate };
    },
  };
