      const maxSpeedX = inGate ? 1.15 : (phase === 'align' ? 0.90 : 1.45);
      const maxSpeedYZ = inGate ? 1.40 : 1.75;
      const tauRefX = inGate ? 5.5 : (phase === 'align' ? 3.4 : 4.8);
      const tauRefYZ = inGate ? 5.5 : 4.8;
