      } else if (inGate) {
        posInt.x *= 0.95;
        posInt.z = clamp(posInt.z + (target.z - p.z) * dt, -0.25, 0.25);
      } else {
        posInt.x *= 0.98;
        posInt.z *= 0.98;
      }
      if (Math.abs(target.y - p.y) < 0.45) {
        posInt.y = clamp(posInt.y + (target.y - p.y) * dt, -0.45, 0.45);
